async function commit(files,{restoreUndo=null}={}){if(storageMode==='session'){state={revision:state.revision+1,files};backupUndo=restoreUndo;if(!restoreUndo)clearBackupReview();return;}const expected=state.revision;const next={revision:expected+1,files};await new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite'),store=tx.objectStore('state');let conflict=false;store.get('workspace').onsuccess=e=>{if((e.target.result?.revision||0)!==expected){conflict=true;tx.abort();return;}store.put(next,'workspace');if(restoreUndo)store.put({...restoreUndo,revision:next.revision},'backup-undo');else store.delete('backup-undo');};tx.oncomplete=resolve;tx.onabort=tx.onerror=()=>reject(Error(conflict?'This workspace was changed in another tab. Reload the page before continuing.':'Saving failed. Existing files have been kept.'));});state=next;backupUndo=restoreUndo;if(!restoreUndo)clearBackupReview();}
