async function removeFile(id){if(busy)return;const index=state.files.findIndex(f=>f.id===id);if(index<0)return;busy=true;render();const removed=state.files[index];try{await commit(state.files.filter(f=>f.id!==id));changed();closeUndo();undo={file:removed,index};$('#undo-bar').hidden=false;timer=setTimeout(closeUndo,30000);$('#status').textContent='File removed. Leaderboard updated automatically.';}catch(e){$('#status').textContent=e.message;}finally{busy=false;render();}}
$('#undo').onclick=async()=>{if(busy||!undo)return;const restore=undo;busy=true;render();clearTimeout(timer);try{const files=[...state.files];files.splice(Math.min(files.length,restore.index),0,restore.file);await commit(files);changed();closeUndo();$('#status').textContent='File restored. Leaderboard updated automatically.';}catch(e){$('#status').textContent=e.message;timer=setTimeout(closeUndo,30000);}finally{busy=false;render();}};
