function closeJpegViewer(){$('#save-jpeg-as').disabled=true;$('#viewer-download').removeAttribute('href');$('#viewer-download').hidden=true;$('#viewer-share').disabled=true;const viewer=$('#jpeg-viewer');if(!viewer)return;if(viewer.open&&typeof viewer.close==='function')viewer.close();else viewer.removeAttribute('open');viewer.classList.remove('viewer-fallback');$('#jpeg-viewer-image').removeAttribute('src');}
