$('#save-jpeg-as').onclick=async()=>{const active=jpegArtifact;if(!active)return;$('#save-jpeg-as').disabled=true;$('#jpeg-viewer-status').textContent='Choose a folder and filename in the save dialog.';const result=await saveJpegAs(active,{host:window,isCurrent:()=>jpegArtifact===active});if(jpegArtifact===active){$('#jpeg-viewer-status').textContent=result.message;$('#save-jpeg-as').disabled=!supportsSaveAs(window);}};
