function currentTournament(){return {name:tournamentName.value,date:tournamentDate.value,time:tournamentTime.value};}
function applyBackupTournament(value){tournamentName.value=value.name;tournamentDate.value=value.date;syncTimeSelectors(value.time);saveTournamentDetails();}
function clearBackupReview(){pendingBackup=null;$('#backup-review').hidden=true;$('#restore-backup-file').value='';}
$('#save-backup').onclick=e=>{if(busy||storageMode==='loading'){e.preventDefault();return;}try{const value=serializeSessionBackup(state.files,currentTournament());if(backupUrl){const old=backupUrl;setTimeout(()=>URL.revokeObjectURL(old),300000);}backupUrl=URL.createObjectURL(new Blob([value],{type:'application/json'}));e.currentTarget.href=backupUrl;$('#backup-status').textContent='Backup download requested. Transfer genting-session-backup.json to your other device, then choose RESTORE BACKUP there.';}catch(error){e.preventDefault();$('#backup-status').textContent=error.message;}};
$('#restore-backup-file').onchange=async e=>{const file=e.target.files?.[0];if(!file||busy)return;clearBackupReview();busy=true;render();try{if(file.size>backupLimit)throw Error('The backup exceeds 30 MB.');const bytes=await readBytes(file);const backup=parseSessionBackup(new TextDecoder('utf-8',{fatal:true}).decode(bytes)),summary=backupSummary(backup);pendingBackup=backup;$('#backup-review-text').textContent=`${file.name}: ${summary.files} files · ${summary.records} records · ${summary.qualified} qualified. Restoring replaces the current ${state.files.length} files and tournament details. UNDO RESTORE is available until the next file change.`;$('#backup-review').hidden=false;$('#backup-status').textContent='Backup validated. Review before restoring.';}catch(error){$('#backup-status').textContent=file.name+': '+error.message+' Existing files have been kept.';}finally{busy=false;render();}};
$('#cancel-backup-restore').onclick=()=>{clearBackupReview();$('#backup-status').textContent='Restore cancelled. Existing files have been kept.';};
$('#confirm-backup-restore').onclick=async()=>{if(busy||!pendingBackup)return;const backup=pendingBackup,previous={files:state.files,tournament:currentTournament()};busy=true;render();try{await commit(backup.files,{restoreUndo:previous});closeUndo();changed();applyBackupTournament(backup.tournament);clearBackupReview();for(const id of ['search-name','search-nationality','search-flight','search-chips'])$('#'+id).value='';$('#backup-status').textContent='Session restored locally. Review the players and confirm the publication policy again before generating a JPEG.';}catch(error){$('#backup-status').textContent=error.message;}finally{busy=false;render();}};
$('#undo-backup-restore').onclick=async()=>{if(busy||!backupUndo)return;const previous=backupUndo;busy=true;render();try{await commit(previous.files);closeUndo();changed();applyBackupTournament(previous.tournament);clearBackupReview();$('#backup-status').textContent='Previous session restored.';}catch(error){$('#backup-status').textContent=error.message;}finally{busy=false;render();}};
if(db)try{const previous=await new Promise((resolve,reject)=>{const tx=db.transaction('state'),r=tx.objectStore('state').get('backup-undo');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(previous?.revision===state.revision)backupUndo=previous;}catch{}render();
